PixelChannels **allocate_pixel_channel_arrays(const Image *images) {
    int max_threads = get_max_threads();
    PixelChannels **channel_arrays = (PixelChannels **)malloc(max_threads * sizeof(PixelChannels *));
    if (channel_arrays == NULL) {
        return NULL;
    }

    int max_cols = get_max_columns(images);
    for (int i = 0; i < max_threads; ++i) {
        channel_arrays[i] = (PixelChannels *)malloc(max_cols * sizeof(PixelChannels));
        if (channel_arrays[i] == NULL) {
            // Clean up previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(channel_arrays[j]);
            }
            free(channel_arrays);
            return NULL;
        }

        for (int j = 0; j < max_cols; ++j) {
            channel_arrays[i][j] = 0;
        }
    }

    return channel_arrays;
}

PixelChannels **allocate_pixel_channel_arrays(const Image *images) {
    int max_threads = sysconf(_SC_NPROCESSORS_ONLN);
    PixelChannels **channels = (PixelChannels **)malloc(max_threads * sizeof(PixelChannels *));
    if (!channels) {
        return NULL;
    }

    int max_cols = 0;
    for (int i = 0; i < images->count; i++) {
        if (images->data[i].width > max_cols) {
            max_cols = images->data[i].width;
        }
    }

    for (int i = 0; i < max_threads; i++) {
        channels[i] = (PixelChannels *)calloc(max_cols, sizeof(PixelChannels));
        if (!channels[i]) {
            for (int j = 0; j < i; j++) {
                free(channels[j]);
            }
            free(channels);
            return NULL;
        }
    }

    return channels;
}

