PixelChannels **allocate_pixel_channel_arrays(const Image *images) {
    int max_threads = get_max_threads();
    PixelChannels **pixel_channels = (PixelChannels **)malloc(max_threads * sizeof(PixelChannels *));
    if (!pixel_channels) {
        return NULL;
    }

    int max_columns = get_max_columns(images);
    for (int i = 0; i < max_threads; i++) {
        pixel_channels[i] = (PixelChannels *)calloc(max_columns, sizeof(PixelChannels));
        if (!pixel_channels[i]) {
            while (i > 0) {
                free(pixel_channels[--i]);
            }
            free(pixel_channels);
            return NULL;
        }
    }

    return pixel_channels;
}

PixelChannels **allocate_pixel_channels(const Image *images) {
    int max_threads = sysconf(_SC_NPROCESSORS_ONLN);
    PixelChannels **channels = (PixelChannels **)malloc(max_threads * sizeof(PixelChannels *));
    if (!channels)
        return NULL;

    int max_cols = 0;
    for (int i = 0; i < images->count; i++) {
        if (images->data[i].cols > max_cols)
            max_cols = images->data[i].cols;
    }

    for (int i = 0; i < max_threads; i++) {
        channels[i] = (PixelChannels *)calloc(max_cols, sizeof(PixelChannels));
        if (!channels[i]) {
            for (int j = 0; j < i; j++)
                free(channels[j]);
            free(channels);
            return NULL;
        }
    }

    return channels;
}
